 final Handler ui=new Handler(Looper.getMainLooper());final ScheduledExecutorService worker=Executors.newSingleThreadScheduledExecutor();final File backups;final SharedPreferences preferences;final Runnable changed;final java.util.function.Consumer<String> error;
 volatile Session session;volatile State state;volatile boolean busy=false,connecting=false,connected=false,destroyed=false;String status="Connect to your Stadium to view its current preset.",host="",mode="Preset",bank="a";boolean tuner=false,focus=false;double tunerReference=Double.NaN;int path=0,pos=1,slot=0,page=0,container=-2;String category="",presetSearch="",modelSearch="";
